const chartFont='';
const $=id=>document.getElementById(id);
const series=['Sample A','Sample B','Reference'];
const palettes={"palette1":["#77B900","#18BBA4","#0074DD","#962EC6","#EF9205","#D94F59","#294A75","#737373"],"palette2":["#1F77B4","#FF7F0E","#2CA02C","#D62728","#9467BD","#8C564B","#E377C2","#7F7F7F","#BCBD22","#17BECF"],"palette3":["#1171BE","#DD5400","#EDB120","#8516D1","#3BAA32","#2FBEEF","#D1048B"]};
function sample(name,title,ylabel,values){return {name,title,xlabel:'Position',ylabel,ymin:'',ymax:'',lower:'',upper:'',sd:false,labels:false,average:false,colors:{},rows:values.flatMap((v,i)=>v.map((n,j)=>({category:`Pos ${i+1}`,series:series[j],value:String(n),sd:''})))}}
let project={version:2,graphs:[sample('BLT','Bond line thickness','Height (mm)',[[19.5,21.8,19.2],[19.5,19.5,18.8],[19.1,19.1,18.5],[22.8,24.5,21.5],[14.2,13,14.6],[14.1,12,14.4]]),sample('Ra','Surface roughness','Ra (µm)',[[1.2,1.1,1.4],[1.2,.5,1.2],[.8,.7,.6],[1.8,.1,.8],[.5,.6,.5],[.5,.8,.5]]),sample('Sa','Areal surface roughness','Sa (µm)',[[2.8,2.2,2.2],[2.2,2.5,2.2],[2.1,2.2,1.9],[2.9,2.7,2.9],[1.5,1.1,1.7],[1.2,1.3,1.4]])]};
let active=0,combined=false; const fields=['title','xlabel','ylabel','ymin','ymax','lower','upper','sd','labels','average'];
const current=()=>project.graphs[active];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function toast(message){$('toast').textContent=message;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',2500)}
function mean(a){return a.reduce((s,x)=>s+x,0)/a.length}function deviation(a){return a.length>1?Math.sqrt(a.reduce((s,x)=>s+(x-mean(a))**2,0)/(a.length-1)):null}
function numbers(text){const parts=String(text).trim().replace(/^\[/,'').replace(/\]$/,'').split(/[,;\s]+/).filter(Boolean);if(!parts.length)throw Error('Enter a measurement.');const a=parts.map(Number);if(a.some(x=>!Number.isFinite(x)))throw Error('Measurements must be finite numbers.');return a}
function rowUsed(r){return !!(r.category.trim()||r.series.trim()||r.value.trim()||r.sd.trim()||r.samples?.some(v=>v.trim()))}
function blankRow(){return {category:'',series:'',type:'raw',samples:[''],value:'',sd:''}}
function normalizeGraph(g){if(g.grouped===undefined)g.grouped=true;if(typeof g.pivoted!=='boolean')g.pivoted=false;if(!palettes[g.palette])g.palette='palette1';if(!g.pivotColors)g.pivotColors={};if(typeof g.otherXLabel!=='string')g.otherXLabel='Series';if(!['wide','narrow'].includes(g.width))g.width='wide';for(const r of g.rows){if(!r.type)r.type=g.mode==='summary'||r.sd.trim()!==''?'summary':'raw';if(!['raw','summary'].includes(r.type))throw Error('Invalid row input type.');if(r.samples!==undefined&&(!Array.isArray(r.samples)||r.samples.length>10000||r.samples.some(v=>typeof v!=='string')))throw Error('Invalid measurement array.');if(!r.samples)r.samples=r.type==='raw'?r.value.replace(/^\[/,'').replace(/\]$/,'').split(/[,;\s]+/).filter(Boolean):[];if(!r.samples.length||r.samples.at(-1).trim())r.samples.push('')}delete g.mode;return g}
function rowStats(r){if(r.type==='summary'){const a=numbers(r.value);if(a.length!==1)throw Error('Enter one mean, or choose Raw data for this row.');const sd=r.sd.trim()===''?null:Number(r.sd);if(sd!==null&&(!Number.isFinite(sd)||sd<0))throw Error('SD must be a nonnegative number.');return {mean:a[0],sd,raw:null,n:null}}const a=r.samples.filter(v=>v.trim()).map(v=>{const parsed=numbers(v);if(parsed.length!==1)throw Error('One measurement per field. Paste an Excel row or column to fill several fields.');return parsed[0]});if(!a.length)throw Error('Enter at least one measurement.');return {mean:mean(a),sd:deviation(a),raw:a,n:a.length}}
function compile(g){const keys=new Set();return g.rows.filter(rowUsed).map((r,i)=>{if(!r.category.trim())throw Error(`Row ${i+1}: enter a category.`);const pivoted=g.grouped&&g.pivoted;const group=g.grouped?(pivoted?r.category.trim():(r.series.trim()||'Series 1')):'Bars';const category=pivoted?(r.series.trim()||'Series 1'):r.category.trim();const key=JSON.stringify([category,group]);if(keys.has(key))throw Error(`Duplicate bar: ${category}${g.grouped?' / '+group:''}. Use one row per bar.`);keys.add(key);try{return {category,series:group,...rowStats(r)}}catch(e){throw Error(`Row ${i+1}: ${e.message}`)}})}
function parseExcelArray(text){const lines=text.trim().split(/\r?\n/).filter(l=>l.trim());if(lines.length>1&&lines.some(l=>l.split('\t').filter(v=>v.trim()).length>1))throw Error('Paste a single Excel row or column for this array.');const vals=text.trim().replace(/^\[/,'').replace(/\]$/,'').split(/[,;\s]+/).filter(Boolean);if(!vals.length||vals.some(v=>!Number.isFinite(Number(v))))throw Error('Paste numeric measurements only, without a header.');return vals}


function colorMap(g){return g.grouped&&g.pivoted?g.pivotColors:g.colors}
function color(g,s,i){const palette=palettes[g.palette]||palettes.palette1;return palette[i%palette.length]}
function svgPlot(g,compact=false){let data=compile(g);if(!data.length)throw Error('Add at least one measurement.');const cats=[...new Set(data.map(r=>r.category))],groups=[...new Set(data.map(r=>r.series))];if(g.average){if(data.some(r=>r.raw===null))throw Error('Overall average needs raw samples for every bar. Use raw data for every row or turn off the average.');if(cats.includes('Overall average'))throw Error('Rename the category “Overall average” to use average bars.');for(const s of groups){const a=data.filter(r=>r.series===s).flatMap(r=>r.raw);data.push({category:'Overall average',series:s,mean:mean(a),sd:deviation(a),n:a.length})}cats.push('Overall average')}
const W=compact?430:(g.width==='narrow'?550:950),H=compact?360:430,L=compact?63:78,R=24,T=compact?48:40,B=72,pw=W-L-R,ph=H-T-B;
const numeric=k=>g[k]===''?null:Number(g[k]);for(const k of ['lower','upper','ymin','ymax'])if(numeric(k)!==null&&!Number.isFinite(numeric(k)))throw Error('Axis bounds and limits must be finite.');if(numeric('lower')!==null&&numeric('upper')!==null&&numeric('lower')>numeric('upper'))throw Error('Lower limit must not exceed upper limit.');
let low=Math.min(0,...data.map(r=>r.mean-(g.sd?(r.sd||0):0)),...['lower','upper'].map(k=>numeric(k)??0));let high=Math.max(0,...data.map(r=>r.mean+(g.sd?(r.sd||0):0)),...['lower','upper'].map(k=>numeric(k)??0));const span=high-low||1;low=numeric('ymin')??(low<0?low-.05*span:0);high=numeric('ymax')??(high+.12*span);if(high<=low)throw Error('Y maximum must be greater than Y minimum.');
const rawStep=(high-low)/6,magnitude=10**Math.floor(Math.log10(rawStep)),fraction=rawStep/magnitude,tickStep=([1,2,2.5,5,10].find(v=>v>=fraction)||10)*magnitude;
const y=v=>T+ph-(v-low)/(high-low)*ph,step=pw/cats.length,bw=step*.8/groups.length,base=y(Math.max(low,Math.min(high,0))),fs=compact?10:12;
let s=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(g.title)}"><rect width="${W}" height="${H}" fill="white"/><style>@font-face{font-family:ChartSans;src:url(data:font/ttf;base64,${chartFont})}text{font-family:ChartSans,'DejaVu Sans',Arial,sans-serif;fill:#000}</style><text x="${L+pw/2}" y="${T-13}" text-anchor="middle" font-size="${compact?13:15}">${esc(g.title)}</text>`;
for(let i=Math.ceil(low/tickStep-1e-9);i*tickStep<=high+tickStep*1e-9;i++){const v=i*tickStep,py=y(v),label=Math.abs(v)<tickStep*1e-8?'0':Number(v.toPrecision(10));s+=`<path d="M${L},${py}h-4" stroke="black" stroke-width=".8"/><text x="${L-8}" y="${py+fs*.35}" text-anchor="end" font-size="${fs}">${label}</text>`}
const clip='clip-'+project.graphs.indexOf(g);s+=`<defs><clipPath id="${clip}"><rect x="${L}" y="${T}" width="${pw}" height="${ph}"/></clipPath></defs><g clip-path="url(#${clip})">`;
for(const [i,c] of cats.entries())for(const [j,gr] of groups.entries()){const r=data.find(r=>r.category===c&&r.series===gr);if(!r)continue;const cx=L+step*(i+.5)+(j-(groups.length-1)/2)*bw,top=Math.min(y(r.mean),base),height=Math.abs(y(r.mean)-base);s+=`<rect x="${cx-bw/2}" y="${top}" width="${bw}" height="${height}" fill="${color(g,gr,j)}" opacity="${c==='Overall average'?.65:1}"><title>${esc(c)} · ${esc(gr)}: ${r.mean.toFixed(3)}${r.sd===null?'':` ± ${r.sd.toFixed(3)} SD`}</title></rect>`;if(g.sd&&r.sd!==null){const a=y(r.mean-r.sd),b=y(r.mean+r.sd);s+=`<path d="M${cx},${a}V${b}M${cx-4},${a}h8M${cx-4},${b}h8" stroke="black" fill="none" stroke-width="1.2"/>`}if(g.labels)s+=`<text x="${cx}" y="${y(r.mean+(g.sd?(r.sd||0):0))-7}" text-anchor="middle" font-size="${compact?8:11}">${Number(r.mean.toFixed(2))}</text>`}
for(const [k,label] of [['lower','Lower'],['upper','Upper']])if(numeric(k)!==null)s+=`<line x1="${L}" x2="${W-R}" y1="${y(numeric(k))}" y2="${y(numeric(k))}" stroke="#D62728" stroke-width="1.2" stroke-dasharray="6 4"/><text x="${W-R-3}" y="${y(numeric(k))-5}" text-anchor="end" font-size="10" style="fill:#D62728">${label}: ${numeric(k)}</text>`;s+='</g>';
s+=`<rect x="${L}" y="${T}" width="${pw}" height="${ph}" fill="none" stroke="black" stroke-width=".8"/>`;
for(const [i,c] of cats.entries()){const x=L+step*(i+.5);s+=`<path d="M${x},${T+ph}v4" stroke="black" stroke-width=".8"/><text x="${x}" y="${T+ph+19}" text-anchor="middle" font-size="${fs}">${esc(c)}</text>`}
s+=`<text x="${L+pw/2}" y="${H-20}" text-anchor="middle" font-size="${fs+1}">${esc(g.xlabel)}</text><text transform="translate(18 ${T+ph/2}) rotate(-90)" text-anchor="middle" font-size="${fs+1}">${esc(g.ylabel)}</text>`;
if(g.grouped){const legendFs=compact?9:11,rowHeight=legendFs+7,maxRows=Math.max(1,Math.floor((ph-20)/rowHeight)),cols=Math.ceil(groups.length/maxRows),rows=Math.ceil(groups.length/cols),colWidth=Math.min(pw/cols-8,Math.max(...groups.map(gr=>gr.length))*legendFs*.62+43),lw=colWidth*cols+12,lh=rows*rowHeight+12,lx=W-R-lw-7,ly=T+7;s+=`<rect x="${lx}" y="${ly}" width="${lw}" height="${lh}" rx="4" fill="white" fill-opacity=".8" stroke="#ccc" stroke-width=".8"/>`;groups.forEach((gr,i)=>{const x=lx+8+Math.floor(i/rows)*colWidth,yy=ly+8+(i%rows)*rowHeight;s+=`<rect x="${x}" y="${yy}" width="23" height="${legendFs}" fill="${color(g,gr,i)}"/><text x="${x+31}" y="${yy+legendFs-1}" font-size="${legendFs}">${esc(gr)}</text>`})}
s+='</svg>';return {svg:s,bars:data.length,groups:groups.length,cats:cats.length,data}}
function render(){syncAverage();syncGraphControls();$('wide').classList.toggle('active',current().width==='wide');$('narrow').classList.toggle('active',current().width==='narrow');$('chart').classList.toggle('narrow',!combined&&current().width==='narrow');try{const selected=combined?project.graphs.filter(g=>g.rows.some(rowUsed)):[current()];if(!selected.length||(!combined&&!current().rows.some(rowUsed))){ $('chart').innerHTML='<div class="emptychart"><strong>Your graph starts here</strong><span>Name a category, then enter samples or a mean and SD.</span></div>';$('chartError').textContent='';$('summary').textContent='No measurements yet';$('export').disabled=true;}else{const plots=selected.map(g=>svgPlot(g,combined));if(combined){const columns=Math.min(3,plots.length),rows=Math.ceil(plots.length/columns);$('chart').innerHTML=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${430*columns} ${360*rows}" role="img" aria-label="Combined figure">${plots.map((p,i)=>p.svg.replace('<svg ',`<svg x="${430*(i%columns)}" y="${360*Math.floor(i/columns)}" width="430" height="360" `)).join('')}</svg>`}else $('chart').innerHTML=plots[0].svg;$('chartError').textContent='';$('summary').textContent=`${plots.reduce((s,p)=>s+p.bars,0)} bars · ${combined?`${plots.length} graphs`:`${plots[0].cats} categories · ${plots[0].groups} series`}`;$('export').disabled=false}}catch(e){$('chartError').textContent=e.message;$('chart').innerHTML='';$('summary').textContent='Check the data and settings';$('export').disabled=true}$('previewtitle').textContent=combined?'Combined figure':current().title;updateComputed()}
function syncAverage(){const unavailable=current().rows.some(r=>rowUsed(r)&&r.type==='summary');$('average').disabled=unavailable;if(unavailable&&current().average){current().average=false;$('average').checked=false}}
function updateComputed(){current().rows.forEach((r,i)=>{const cells=$('rows').children[i]?.querySelectorAll('[data-computed]');if(!cells||r.type!=='raw')return;try{const stat=rowStats(r);cells[0].textContent=Number(stat.mean.toFixed(3));cells[1].textContent=stat.sd===null?'n/a':Number(stat.sd.toFixed(3));cells[2].textContent=stat.n}catch{cells.forEach(c=>c.textContent='—')}})}
function makeInput(value,label,oninput,type='text',placeholder=''){const input=document.createElement('input');input.value=value;input.type=type;input.setAttribute('aria-label',label);input.placeholder=placeholder;if(type==='number')input.step='any';input.oninput=()=>oninput(input.value);return input}
function paintSamples(wrap,r,i){wrap.innerHTML='';function addSample(j){const input=makeInput(r.samples[j],`Measurement ${j+1}, row ${i+1}`,v=>{r.samples[j]=v;r.value=r.samples.filter(x=>x.trim()).join(', ');if(j===r.samples.length-1&&v.trim()){r.samples.push('');addSample(j+1)}render()});input.onkeydown=e=>{if((e.key!=='Enter'&&e.key!=='ArrowRight')||e.altKey||e.ctrlKey||e.metaKey||e.shiftKey)return;e.preventDefault();if(j===r.samples.length-1){r.samples.push('');addSample(j+1)}const next=wrap.querySelectorAll('input')[j+1];next.focus();next.select();next.scrollIntoView({block:'nearest',inline:'nearest'})};input.inputMode='decimal';input.placeholder='+';input.className='sampleinput';input.onpaste=e=>{const text=e.clipboardData.getData('text');if(!/[\t\n,;]/.test(text))return;e.preventDefault();try{const vals=parseExcelArray(text);r.samples.splice(j,r.samples[j].trim()?1:0,...vals);r.samples=r.samples.filter(v=>v.trim());r.samples.push('');r.value=r.samples.filter(v=>v.trim()).join(', ');paintSamples(wrap,r,i);render();toast(`${vals.length} measurements pasted`)}catch(err){toast(err.message)}};wrap.append(input);if(j===r.samples.length-1)wrap.scrollLeft=wrap.scrollWidth}r.samples.forEach((_,j)=>addSample(j))}
function paintRows(){const g=current();$('rows').innerHTML='';$('tableHead').innerHTML='<tr>'+[g.grouped?(g.pivoted?'Category · color':'Category · axis'):'Category',...(g.grouped?[g.pivoted?'Series · axis':'Series · color']:[]),'Mean','SD','n','Input type','Add data',''].map(h=>`<th>${h}</th>`).join('')+'</tr>';g.rows.forEach((r,i)=>{const tr=document.createElement('tr');for(const key of ['category',...(g.grouped?['series']:[])]){const td=document.createElement('td');const input=makeInput(r[key],`${key}, row ${i+1}`,v=>{r[key]=v;render()},'text',key==='category'?'Category A':'Series 1');td.append(input);tr.append(td)}const typecell=document.createElement('td'),select=document.createElement('select');select.setAttribute('aria-label',`Input type, row ${i+1}`);for(const [value,label]of [['raw','Raw data'],['summary','Mean + SD']]){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o)}select.value=r.type;select.onchange=()=>{if(select.value==='summary'){try{const stat=rowStats(r);r.value=String(stat.mean);r.sd=stat.sd===null?'':String(stat.sd)}catch{r.value='';r.sd=''}}else{r.value=r.samples.filter(v=>v.trim()).join(', ');r.sd=''}r.type=select.value;paintRows();render()};typecell.append(select);const measurement=document.createElement('td');measurement.className='measurecell';if(r.type==='raw'){const wrap=document.createElement('div');wrap.className='samples';paintSamples(wrap,r,i);measurement.append(wrap)}else{const hint=document.createElement('span');hint.className='providedhint';hint.textContent='← Enter mean + SD';measurement.append(hint)}for(const [key,label]of [['value','Mean'],['sd','SD']]){const td=document.createElement('td');if(r.type==='raw'){td.className='computed';td.dataset.computed=key;td.textContent='—'}else{const input=makeInput(r[key],`${label}, row ${i+1}`,v=>{r[key]=v;render()},'number',key==='value'?'Mean':'Optional');if(key==='sd')input.min=0;td.append(input)}tr.append(td)}const n=document.createElement('td');n.className='computed';if(r.type==='raw')n.dataset.computed='n';n.textContent='—';tr.append(n);tr.append(typecell);tr.append(measurement);const td=document.createElement('td'),del=document.createElement('button');del.textContent='×';del.setAttribute('aria-label',`Delete row ${i+1}`);del.onclick=()=>{g.rows.splice(i,1);paintRows();render()};td.append(del);tr.append(td);$('rows').append(tr)});updateComputed()}

function load(){const g=current();$('tabs').innerHTML='';project.graphs.forEach((gr,i)=>{const b=document.createElement('button');b.textContent=gr.name;b.className=i===active?'active':'';b.onclick=()=>{active=i;load()};$('tabs').append(b);if(i===active){const close=document.createElement('button');close.textContent='×';close.className='closegraph';close.setAttribute('aria-label','Delete '+gr.name);close.onclick=()=>{project.graphs.splice(i,1);if(!project.graphs.length)project.graphs.push(normalizeGraph({name:'New graph',title:'New graph',grouped:false,width:'wide',xlabel:'Category',ylabel:'Value',ymin:'',ymax:'',lower:'',upper:'',sd:true,labels:true,average:false,colors:{},rows:[blankRow()]}));active=Math.min(i,project.graphs.length-1);load()};$('tabs').append(close)}});for(const id of fields){if($(id).type==='checkbox')$(id).checked=g[id];else $(id).value=g[id]}$('pasteError').textContent='';$('paste').value='';$('single').classList.toggle('active',!combined);$('combined').classList.toggle('active',combined);$('modeBadge').textContent=g.grouped?'CATEGORIES + SERIES':'CATEGORIES';$('dataHelp').textContent='Choose Raw data or Mean + SD for each row. Paste an Excel row or column into any measurement field.';$('pasteHelp').textContent=g.grouped?'Columns: Category, Series, Measurements (comma-separated). Add a fourth SD column for supplied statistics.':'Columns: Category, Measurements (comma-separated). Add a third SD column for supplied statistics.';document.querySelector('aside .small').textContent='Raw data uses sample SD (n − 1). At least two samples are needed for SD. Overall averages require all rows to contain raw data.';$('dataStatus').textContent='Your measurements · browser only';paintRows();render()}

for(const id of fields)$(id).oninput=()=>{current()[id]=$(id).type==='checkbox'?$(id).checked:$(id).value;render()};
$('single').onclick=()=>{combined=false;$('single').classList.add('active');$('combined').classList.remove('active');render()};$('combined').onclick=()=>{combined=true;$('combined').classList.add('active');$('single').classList.remove('active');render()};
$('add').onclick=()=>{current().rows.push(blankRow());paintRows();$('rows').lastElementChild.querySelector('input').focus()};
$('apply').onclick=()=>{try{const lines=$('paste').value.trim().split(/\r?\n/).filter(l=>l.trim());if(!lines.length)throw Error('Paste a table first.');if(/^category\t/i.test(lines[0]))lines.shift();const grouped=current().grouped;const rows=lines.map((l,i)=>{const a=l.split('\t');const offset=grouped?1:0;if(a.length<2+offset||a.length>3+offset)throw Error(`Line ${i+1}: expected ${2+offset} or ${3+offset} columns.`);const value=a[1+offset].trim(),sd=(a[2+offset]||'').trim();const row={category:a[0].trim(),series:grouped?a[1].trim():'',value,sd,type:sd!==''?'summary':'raw',samples:['']};if(row.type==='raw'){row.samples=[...parseExcelArray(value),'']}return row});const g={...current(),rows};compile(g);current().rows=rows;paintRows();render();$('pasteError').textContent='';toast('Table imported')}catch(e){$('pasteError').textContent=e.message}};

function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('export').onclick=()=>{const svg=$('chart').querySelector('svg').outerHTML;download(svg,combined?'combined-figure.svg':`${current().name}.svg`,'image/svg+xml')};
$('save').onclick=()=>{download(JSON.stringify(project,null,2),'plot-studio-project.json','application/json');toast('Project saved with data and settings')};$('open').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const f=$('file').files[0];if(!f)return;if(f.size>2000000)throw Error('Project file is too large for this draft.');const p=JSON.parse(await f.text());if(![1,2].includes(p.version)||!Array.isArray(p.graphs)||(!p.graphs.length||p.graphs.length>50))throw Error('Choose a Plot Studio project with 1 to 50 graphs.');for(const g of p.graphs){if(!g||!Array.isArray(g.rows)||!g.colors||g.rows.length>5000)throw Error('Invalid project data.');for(const k of ['name',...fields.filter(x=>!['sd','labels','average'].includes(x))])if(typeof g[k]!=='string')throw Error(`Invalid project setting: ${k}`);for(const k of ['sd','labels','average'])if(typeof g[k]!=='boolean')throw Error('Invalid display options.');for(const v of Object.values(g.colors))if(!/^#[0-9a-f]{6}$/i.test(v))throw Error('Invalid series color.');for(const r of g.rows)for(const k of ['category','series','value','sd'])if(typeof r[k]!=='string')throw Error('Invalid measurement row.');for(const value of Object.values(g.pivotColors||{}))if(typeof value!=='string'||!/^#[0-9a-f]{6}$/i.test(value))throw Error('Invalid pivot color.');if(g.grouped!==undefined&&typeof g.grouped!=='boolean')throw Error('Invalid graph structure.');normalizeGraph(g);compile(g)}p.version=2;project=p;active=0;load();toast('Project opened')}catch(e){toast(e.message)}$('file').value=''};project.graphs.forEach(normalizeGraph);

$('newGraph').onclick=()=>{$('newGraphName').value='';document.querySelector('input[name=graphStructure][value=categories]').checked=true;$('newGraphError').textContent='';$('newGraphDialog').showModal();$('newGraphName').focus()};
$('closeDialog').onclick=$('cancelDialog').onclick=()=>$('newGraphDialog').close();
$('newGraphForm').onsubmit=e=>{e.preventDefault();const name=$('newGraphName').value.trim();if(!name){$('newGraphError').textContent='Enter a graph name.';return}if(project.graphs.some(g=>g.name.toLowerCase()===name.toLowerCase())){$('newGraphError').textContent='Choose a name that is not already in use.';return}if(project.graphs.length>=50){$('newGraphError').textContent='This project already contains 50 graphs.';return}const grouped=document.querySelector('input[name="graphStructure"]:checked').value==='series';project.graphs.push({name,title:name,grouped,pivoted:false,palette:'palette1',pivotColors:{},otherXLabel:'Series',width:'wide',xlabel:'Category',ylabel:'Value',ymin:'',ymax:'',lower:'',upper:'',sd:true,labels:true,average:false,colors:{},rows:[blankRow()]});active=project.graphs.length-1;combined=false;$('newGraphDialog').close();load();$('rows').querySelector('input').focus();toast(grouped?'Categories and series graph created':'Categories graph created')};
$('wide').onclick=()=>{current().width='wide';render()};$('narrow').onclick=()=>{current().width='narrow';render()};

function syncGraphControls(){const g=current();$('pivot').disabled=!g.grouped;$('pivot').setAttribute('aria-pressed',String(!!g.pivoted));$('pivot').classList.toggle('selected',!!g.pivoted);$('pivot').title=g.grouped?'Swap the axis and color dimensions':'Pivot is available for graphs with categories and series';$('palette').value=g.palette||'palette1';$('dimensionRoles').textContent=g.grouped?(g.pivoted?'Axis: Series  ·  Color: Category':'Axis: Category  ·  Color: Series'):'Axis: Category';}
$('pivot').onclick=()=>{const g=current();if(!g.grouped)return;g.pivoted=!g.pivoted;[g.xlabel,g.otherXLabel]=[g.otherXLabel,g.xlabel];$('xlabel').value=g.xlabel;paintRows();render()};
$('palette').onchange=()=>{const g=current();g.palette=$('palette').value;g.colors={};g.pivotColors={};render()};

load();
